    descriptionAdvanced: {
      de: "Aley liegt auf 800 Metern Höhe im Libanongebirge, rund 17 Kilometer südöstlich von Beirut, und zählt etwa 130.000 Einwohner. Die Stadt entwickelte sich im 19. Jahrhundert zur beliebtesten Sommerresidenz reicher Beiruter Familien und arabischer Adliger, weshalb sie den Beinamen Braut der Sommerresorts erhielt. Während des französischen Mandats (1920–1943) wurden zahlreiche prächtige Villen und Hotels im Mandatsstil errichtet. Die Bevölkerung ist gemischt mit einer drusischen Mehrheit und bedeutenden christlichen und sunnitischen Minderheiten. Während des Bergkriegs von 1983 bis 1984 zwischen Drusen und Christen wurde die Region schwer getroffen. Die Eisenbahnlinie Beirut–Damaskus, 1895 von einer französischen Gesellschaft gebaut, machte Aley zum wichtigsten Bahnhof der Bergregion.",
      hu: "Aley (Aleyh) egy hegyvidéki város a Libanon-hegységben, Bejrúttól mindössze 17 kilométerre keletre. Magaslati fekvése (kb. 800-900 méter) és kellemes nyári klímája miatt a 20. század eleje óta a gazdag bejrútiak és a Perzsa-öböl menti országok turistáinak egyik legnépszerűbb nyári menedéke. A települést gyakran a nyár fővárosaként is emlegetik. A városképet elegáns 19. századi oszmán kori kővillák és modern luxusapartmanok keveréke határozza meg. Az Aley Souk (piac) a város szíve, amely nyáron éjszakába nyúlóan tele van élettel, kávézókkal, éttermekkel és üzletekkel. Történelmileg a terület a drúz közösség egyik fontos központja volt, és a lakosság nagy része ma is drúz vallású. A város fái között gyakori a fenyő, amely friss levegőt biztosít a völgyben rekedt nyári hőség elől menekülőknek. Aley gazdasága majdnem teljes egészében a nyári turizmusra és az ingatlanpiacra épül.",
      ro: "Aley este un oraș montan situat în Munții Liban, la doar 17 kilometri est de Beirut. Datorită altitudinii sale (aprox. 800-900 de metri) și climatului blând de vară, a devenit din prima jumătate a secolului al XX-lea un refugiu estival preferat pentru beiruteni și turiștii din țările Golfului Persic. Așezarea este adesea supranumită capitala verii. Peisajul urban se caracterizează printr-un amestec de vile elegante din piatră din perioada otomană (secolul al XIX-lea) și apartamente moderne de lux. Piața centrală (Aley Souk) este inima orașului, fiind plină de viață în serile de vară, cu numeroase cafenele, restaurante și magazine. Istoric, zona a fost un centru important pentru comunitatea druză, iar o mare parte din populația de astăzi aparține acestei religii. Pinii sunt foarte răspândiți în zonă, oferind aer proaspăt celor care fug de căldura verii. Economia orașului Aley depinde aproape în întregime de turismul estival și imobiliare.",
      en: "Aley is a mountainous city in the Mount Lebanon range, located just 17 kilometers east of Beirut. Due to its elevation (approximately 800-900 meters) and pleasant summer climate, it has been a highly popular summer retreat for affluent Beirutis and tourists from the Persian Gulf states since the early 20th century. The settlement is frequently referred to as the Capital of the Summer. The urban landscape features a mix of elegant 19th-century Ottoman-era stone villas and modern luxury apartments. The Aley Souk (market) is the vibrant heart of the city, bustling late into the night during the summer season with cafes, restaurants, and shops. Historically, the area has been a significant center for the Druze community, and a large portion of the current population adheres to the Druze faith. Pine trees are abundant in the city, providing fresh air for those escaping the coastal summer heat. Aley's economy is almost entirely driven by summer tourism and real estate.",
      es: "Aley se encuentra a 800 metros de altitud en la cordillera del Líbano, a unos 17 kilómetros al sureste de Beirut, y cuenta con unos 130.000 habitantes. La ciudad se convirtió en el siglo XIX en la residencia de verano favorita de las familias ricas de Beirut y de la nobleza árabe, por lo que recibió el sobrenombre de 'Novia de los centros de veraneo'. Durante el mandato francés (1920-1943), se construyeron numerosas villas y hoteles magníficos al estilo del mandato. La población es mixta, con una mayoría drusa e importantes minorías cristianas y suníes. Durante la Guerra de la Montaña, entre 1983 y 1984, la región se vio gravemente afectada. La línea ferroviaria Beirut-Damasco, construida en 1895 por una empresa francesa, convirtió a Aley en la estación más importante de la región montañosa.",
      pt: "Aley situa-se a 800 metros de altitude na cordilheira do Líbano, cerca de 17 quilómetros a sudeste de Beirute, e tem cerca de 130.000 habitantes. A cidade tornou-se no século XIX a residência de verão favorita das famílias ricas de Beirute e da nobreza árabe, razão pela qual recebeu a alcunha de 'Noiva das estâncias de verão'. Durante o mandato francês (1920–1943), foram construídas numerosas moradias e hotéis magníficos no estilo do mandato. A população é mista, com uma maioria drusa e importantes minorias cristãs e sunitas. Durante a Guerra da Montanha de 1983 a 1984, a região foi gravemente atingida. A linha ferroviária Beirute-Damasco, construída em 1895 por uma empresa francesa, tornou Aley a estação mais importante da região montanhosa.",
      fr: "Située à 800 mètres d'altitude dans la chaîne du Mont-Liban, à environ 17 kilomètres au sud-est de Beyrouth, Aley compte environ 130 000 habitants. Au XIXe siècle, la ville est devenue la résidence d'été favorite des riches familles beyrouthines et de la noblesse arabe, ce qui lui a valu le surnom de 'Mariée des stations estivales'. Pendant le mandat français (1920-1943), de nombreuses villas et hôtels magnifiques ont été construits dans le style du mandat. La population est mixte, avec une majorité druze et d'importantes minorités chrétiennes et sunnites. La région a été durement touchée pendant la guerre de la Montagne de 1983 à 1984. La ligne de chemin de fer Beyrouth-Damas, construite en 1895 par une société française, a fait d'Aley la gare la plus importante de la région montagneuse.",
    },
