      es: ["Conocida por la elaboración de limonada fresca.", "Popular por su vibrante vida nocturna y sus playas."],
      pt: ["Conhecida pela produção de limonada fresca.", "Popular pela sua vida noturna vibrante e pelas praias."],
      fr: ["Connue pour sa fabrication de limonade fraîche.", "Prisée pour sa vie nocturne animée et ses plages."],
