      ro: ["Hermel se află în nordul extrem al Văii Bekaa, de-a lungul râului Orontes.", "Orașul este cel mai important centru de rafting pe ape repezi din Liban.", "În apropiere se află Kamouh el Hermel, un monument antic sub formă de piramidă.", "Populația este formată din șiiți, cu tradiții tribale și de clan puternice.", "Piscicultura de păstrăv este semnificativă, folosind apele râului Orontes."],
      en: ["Hermel lies at the northern end of the Beqaa Valley along the Orontes River.", "The city is Lebanon's most prominent destination for whitewater rafting.", "Nearby stands Kamouh el Hermel, an ancient pyramid-shaped stone monument.", "Its population is mainly Shia Muslim, characterized by strong clan traditions.", "Trout farming is a significant industry, utilizing the waters of the Orontes."],
      es: ["Unos 30.000 habitantes a 700 metros de altitud", "En el extremo norte del valle de la Becá", "Fuente del río Orontes en las cercanías", "Pirámide de Hermel del siglo I o II a. C.", "Pirámide de 27 metros de altura con relieves de caza", "Población de mayoría chií", "Punto de partida popular para rafting", "Mandato Francés de 1920 a 1943"],
      pt: ["Cerca de 30.000 habitantes a 700 metros de altitude", "No extremo norte do vale de Bekaa", "Nascente do rio Orontes nas proximidades", "Pirâmide de Hermel do século I ou II a.C.", "Pirâmide com 27 metros de altura com relevos de caça", "População de maioria xiita", "Ponto de partida popular para rafting", "Mandato francês de 1920 a 1943"],
      fr: ["Environ 30 000 habitants à 700 mètres d'altitude", "À l'extrême nord de la plaine de la Bekaa", "Source de l'Oronte à proximité", "Pyramide d'Hermel datant du Ier ou IIe siècle av. J.-C.", "Pyramide de 27 mètres de haut avec reliefs de chasse", "Population à majorité chiite", "Point de départ prisé pour le rafting", "Mandat français de 1920 à 1943"],
