    descriptionAdvanced: {
      de: "Chekka liegt im Norden Libanons rund 65 Kilometer nördlich von Beirut an der Mittelmeerküste und zählt etwa 12.000 Einwohner. Die mehrheitlich griechisch-orthodoxe Stadt ist seit dem frühen 20. Jahrhundert das wichtigste Zentrum der libanesischen Zementindustrie: Die Cimenterie Nationale wurde 1953 gegründet, gefolgt von Holcim Liban und Cimenterie Libanaise. Die drei großen Zementwerke produzieren jährlich über 5 Millionen Tonnen und prägen die Wirtschaft der Region maßgeblich. Auch die Papierindustrie ist hier vertreten. Während des französischen Mandats (1920–1943) wurde der industrielle Aufstieg eingeleitet. Die Strände von Chekka mit ihren markanten weißen Kalksteinklippen ziehen Touristen an, und mehrere Strandresorts haben sich entlang der Küste angesiedelt. Die Verschmutzung durch die Zementwerke ist seit Jahren ein Streitpunkt.",
      hu: "Chekka egy jelentős tengerparti ipari város Észak-Libanonban, Batroun és Tripoli között. Bár festői partvidékkel és gyönyörű, homokos strandokkal rendelkezik, a város arculatát és gazdaságát évtizedek óta a nehézipar határozza meg. Chekka Libanon cement- és papírgyártásának központja, hatalmas ipari komplexumai, mint a Cimenterie Nationale, biztosítják az ország építőanyag-ellátásának nagy részét. Az ipari jelleg ellenére a Chekka melletti part menti vizeket sokan látogatják a Ras al-Chaqaa hegyfok alatti természetes barlangok és búvárkodásra alkalmas sziklák miatt. A település körül kiterjedt olajfaültetvények és fügefa-ligetek találhatók, amelyek kiegészítik a helyi gazdaságot. A lakosság többségét maronita és görög ortodox keresztények alkotják, és a városban több modern templom, valamint történelmi szentély, például a tengerre néző Szűz Mária-templom áll.",
      ro: "Chekka este un important oraș industrial de coastă din nordul Libanului, situat între Batroun și Tripoli. Deși are o coastă pitorească și plaje frumoase cu nisip, identitatea și economia orașului au fost definite de industria grea de zeci de ani. Chekka este centrul producției de ciment și hârtie din Liban; complexele sale industriale masive, cum ar fi Cimenterie Nationale, furnizează o mare parte din materialele de construcție ale țării. În ciuda naturii sale industriale, apele de coastă de lângă Chekka sunt vizitate de mulți pentru peșterile naturale de sub promontoriul Ras al-Chaqaa și stâncile potrivite pentru scufundări. Așezarea este înconjurată de plantații extinse de măslini și livezi de smochini, care suplimentează economia locală. Majoritatea populației este formată din creștini maroniți și greco-ortodocși, iar orașul are mai multe biserici moderne și sanctuare istorice, cum ar fi o Biserică a Fecioarei Maria cu vedere la mare.",
      en: "Chekka is a significant coastal industrial town in northern Lebanon, situated between Batroun and Tripoli. Although it features a picturesque coastline and beautiful sandy beaches, the town's identity and economy have been defined by heavy industry for decades. Chekka is the national center for cement and paper production; its massive industrial complexes, such as Cimenterie Nationale, supply a vast majority of the country's building materials. Despite its heavily industrial nature, the coastal waters near Chekka are frequently visited by divers exploring the natural caves beneath the Ras al-Chaqaa headland and the dramatic offshore cliffs. The settlement is also surrounded by extensive olive groves and fig orchards, which supplement the local economy. The demographic majority consists of Maronite and Greek Orthodox Christians, and the town features several modern churches as well as historical sanctuaries, such as a Church of the Virgin Mary overlooking the sea.",
      es: "Chekka se encuentra en el norte del Líbano, a unos 65 kilómetros al norte de Beirut, en la costa mediterránea, y cuenta con unos 12.000 habitantes. La ciudad, mayoritariamente ortodoxa griega, es desde principios del siglo XX el centro más importante de la industria del cemento libanesa: la Cimenterie Nationale se fundó en 1953, seguida por Holcim Liban y Cimenterie Libanaise. Las tres grandes plantas de cemento producen anualmente más de 5 millones de toneladas y marcan de forma decisiva la economía de la región. También la industria del papel está presente aquí. Durante el Mandato Francés (1920-1943) se inició el auge industrial. Las playas de Chekka, con sus característicos acantilados de piedra caliza blanca, atraen a turistas, y varios complejos turísticos se han establecido a lo largo de la costa. La contaminación provocada por las fábricas de cemento ha sido un punto de conflicto durante años.",
      pt: "Chekka situa-se no norte do Líbano, cerca de 65 quilómetros a norte de Beirute, na costa mediterrânica, e conta com cerca de 12.000 habitantes. A cidade, maioritariamente ortodoxa grega, é desde o início do século XX o centro mais importante da indústria de cimento libanesa: a Cimenterie Nationale foi fundada em 1953, seguida pela Holcim Liban e pela Cimenterie Libanaise. As três grandes fábricas de cimento produzem anualmente mais de 5 milhões de toneladas e moldam significativamente a economia da região. A indústria do papel também está representada aqui. Durante o mandato francês (1920-1943), iniciou-se a ascensão industrial. As praias de Chekka, com as suas distintas falésias de calcário branco, atraem turistas, e vários complexos balneares estabeleceram-se ao longo da costa. A poluição causada pelas cimenteiras tem sido um ponto de discórdia há anos.",
      fr: "Chekka est située au nord du Liban, à environ 65 kilomètres au nord de Beyrouth sur la côte méditerranéenne, et compte environ 12 000 habitants. La ville, majoritairement grecque-orthodoxe, est depuis le début du XXe siècle le centre le plus important de l'industrie du ciment libanaise : la Cimenterie Nationale a été fondée en 1953, suivie par Holcim Liban et la Cimenterie Libanaise. Les trois grandes cimenteries produisent annuellement plus de 5 millions de tonnes et marquent l'économie régionale de façon prépondérante. L'industrie du papier y est également présente. L'essor industriel a été amorcé durant le mandat français (1920-1943). Les plages de Chekka, avec leurs falaises de calcaire blanc caractéristiques, attirent les touristes, et plusieurs complexes hôteliers se sont installés le long de la côte. La pollution générée par les cimenteries est un sujet de discorde depuis des années.",
    },
